import {
  Component,
  EventEmitter,
  Input,
  Output,
  signal,
  ChangeDetectionStrategy
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RobotEmotion, ColorThemePreset } from '../core/emotions/emotion-types';
import { EMOTION_PRESETS } from '../core/emotions/emotion-definitions';

@Component({
  selector: 'clip-eva-controls',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './emotion-controls.component.html',
  styleUrl: './emotion-controls.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ClipEvaControlsComponent {
  @Input({ required: true }) activeEmotion = 'happy' as RobotEmotion;

  @Output() emotionChange = new EventEmitter<RobotEmotion>();
  @Output() blinkTrigger = new EventEmitter<void>();
  @Output() autoBlinkToggle = new EventEmitter<boolean>();
  @Output() hoverToggle = new EventEmitter<boolean>();
  @Output() pulseToggle = new EventEmitter<boolean>();
  @Output() glowIntensityChange = new EventEmitter<number>();
  @Output() eyeScaleChange = new EventEmitter<number>();
  @Output() eyeSpacingChange = new EventEmitter<number>();
  @Output() colorThemeChange = new EventEmitter<{ primary: string; secondary: string }>();
  @Output() customImageSelect = new EventEmitter<string>();
  @Output() visorTransformChange = new EventEmitter<{
    position: { x: number; y: number; z: number };
    rotation: { x: number; y: number; z: number };
    scale: { x: number; y: number };
  }>();

  readonly emotionList = Object.values(EMOTION_PRESETS);

  // Settings State Signals
  readonly autoBlink = signal<boolean>(true);
  readonly hoverEnabled = signal<boolean>(true);
  readonly pulseEnabled = signal<boolean>(true);
  readonly glowIntensity = signal<number>(1.2);
  readonly eyeScale = signal<number>(1.0);
  readonly eyeSpacing = signal<number>(160);
  readonly isTuningOpen = signal<boolean>(false);

  // Visor fine-tuning values
  readonly visorPosX = signal<number>(0.338);
  readonly visorPosY = signal<number>(0.180);
  readonly visorPosZ = signal<number>(0.0);
  readonly visorRotX = signal<number>(0.10);
  readonly visorScaleX = signal<number>(1.0);
  readonly visorScaleY = signal<number>(1.0);

  readonly colorThemes: ColorThemePreset[] = [
    { name: 'Cyan Neon', primary: '#00f0ff', secondary: '#3b82f6', previewClass: 'theme-cyan' },
    { name: 'Cyber Violet', primary: '#a855f7', secondary: '#3b82f6', previewClass: 'theme-violet' },
    { name: 'Neon Rose', primary: '#f43f5e', secondary: '#ec4899', previewClass: 'theme-rose' },
    { name: 'Emerald OLED', primary: '#10b981', secondary: '#06b6d4', previewClass: 'theme-emerald' },
    { name: 'Solar Amber', primary: '#f59e0b', secondary: '#ef4444', previewClass: 'theme-amber' }
  ];

  selectEmotion(emotion: RobotEmotion): void {
    this.emotionChange.emit(emotion);
  }

  onTriggerBlink(): void {
    this.blinkTrigger.emit();
  }

  onAutoBlinkToggle(): void {
    this.autoBlink.update((v) => !v);
    this.autoBlinkToggle.emit(this.autoBlink());
  }

  onHoverToggle(): void {
    this.hoverEnabled.update((v) => !v);
    this.hoverToggle.emit(this.hoverEnabled());
  }

  onPulseToggle(): void {
    this.pulseEnabled.update((v) => !v);
    this.pulseToggle.emit(this.pulseEnabled());
  }

  onGlowChange(value: number): void {
    this.glowIntensity.set(value);
    this.glowIntensityChange.emit(value);
  }

  onScaleChange(value: number): void {
    this.eyeScale.set(value);
    this.eyeScaleChange.emit(value);
  }

  onSpacingChange(value: number): void {
    this.eyeSpacing.set(value);
    this.eyeSpacingChange.emit(value);
  }

  onThemeSelect(theme: ColorThemePreset): void {
    this.colorThemeChange.emit({ primary: theme.primary, secondary: theme.secondary });
  }

  onCustomFileSelected(event: Event): void {
    const input = event.target as HTMLInputElement;
    if (input.files && input.files[0]) {
      const file = input.files[0];
      const blobUrl = URL.createObjectURL(file);
      this.customImageSelect.emit(blobUrl);
    }
  }

  toggleTuning(): void {
    this.isTuningOpen.update((v) => !v);
  }

  emitVisorTransform(): void {
    this.visorTransformChange.emit({
      position: { x: this.visorPosX(), y: this.visorPosY(), z: this.visorPosZ() },
      rotation: { x: this.visorRotX(), y: 0, z: 0 },
      scale: { x: this.visorScaleX(), y: this.visorScaleY() }
    });
  }

  onVisorPosXChange(val: number): void {
    this.visorPosX.set(val);
    this.emitVisorTransform();
  }

  onVisorPosYChange(val: number): void {
    this.visorPosY.set(val);
    this.emitVisorTransform();
  }

  onVisorPosZChange(val: number): void {
    this.visorPosZ.set(val);
    this.emitVisorTransform();
  }

  onVisorRotXChange(val: number): void {
    this.visorRotX.set(val);
    this.emitVisorTransform();
  }
}
